__attribute__((target("avx2,fma")))
void radix13_z_t2csgnt_bwd_avx2(
    const double *            zin,
    const double *            zin_unused,
    double       *            zout,
    double       *            zout_unused,
    const double * tw_re, const double * tw_im,
    size_t Ls, size_t Gs, size_t OLs, size_t OGs, size_t count)
{
    /* t2csgn: in-kernel group loop over the natural-base table (zin_unused = obase, stride count); Gs = groups; one call per stage. zout_unused, when non-null, is the GROUP ORDER (size_t per group): the loop walks the groups in that order — the driver passes natural-base order so consecutive groups fill adjacent output lines (one write-allocate per line instead of one per complex); the input reads scatter instead, one contiguous block each. */
    const size_t *obase = (const size_t *)zin_unused;
    const size_t *gord = (const size_t *)zout_unused;
    for (size_t gq = 0; gq < Gs; gq++) {
        const size_t g = gord ? gord[gq] : gq;
        for (size_t c = 0; c < Ls; c++)
            _t2csgn13_body(zin + 2 * (g * count * 13 * Ls + c), 0,
                           zout + 2 * (obase[g * count] + c), 0,
                           tw_re, tw_im + 8 * g, Ls, 13 * Ls, OLs, OGs, count);
    }
}
